import React, { useState } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { Eye, EyeOff, Lock, Mail, User } from "lucide-react";
import { useAuth } from "./AuthContext";
import { useTheme } from "./ThemeContext";
import { h, f } from "./h";
import { apiFetch } from "./api";
import { Button, Field, GlassPanel, LogoMark, RefImage, TextInput, ThemeToggleButton } from "./ui";

export function LoginPage() {
  const nav = useNavigate();
  const loc = useLocation();
  const { login } = useAuth();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [show, setShow] = useState(false);
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);

  const onSubmit = async (e) => {
    e.preventDefault();
    setErr("");
    setLoading(true);
    try {
      const data = await login(email.trim(), password);
      const role = data?.user?.role;
      if (role === "seller") {
        nav("/vendor/dashboard", { replace: true });
      } else {
        nav("/shop", { replace: true });
      }
    } catch (ex) {
      const msg = ex.message || "Login failed";
      if (ex.status === 403 && /verify/i.test(msg)) {
        setErr(`${msg} Use the link on the verify-email page, or ask your admin to enable AUTH_SKIP_EMAIL_VERIFICATION for local dev.`);
      } else if (ex.status === 400) {
        setErr(msg === "Validation error" ? "Check your email and password format." : msg);
      } else {
        setErr(msg);
      }
    } finally {
      setLoading(false);
    }
  };

  return h("div", { className: "relative min-h-screen overflow-hidden" }, [
    h(RefImage, {
      key: "bg",
      n: 17,
      alt: "",
      className: "pointer-events-none absolute inset-0 h-full w-full object-cover opacity-40 dark:opacity-25"
    }),
    h("div", {
      key: "overlay",
      className:
        "absolute inset-0 bg-gradient-to-b from-slate-100/90 via-slate-100/80 to-slate-200/90 dark:from-night-950/95 dark:via-night-950/90 dark:to-slate-950/95"
    }),
    h(
      "div",
      { key: "content", className: "relative z-10 mx-auto flex min-h-screen max-w-lg flex-col px-4 py-8 sm:px-6" },
      [
        h("div", { key: "topbar", className: "mb-6 flex items-center justify-between" }, [
          h(Link, { key: "home", to: "/shop", className: "flex items-center gap-2" }, [
            h(LogoMark, { key: "lm" }),
            h(
              "span",
              { key: "nm", className: "font-display text-xl font-semibold text-slate-900 dark:text-white" },
              "BrewMart"
            )
          ]),
        ]),
        h(GlassPanel, { key: "panel", className: "mx-auto w-full max-w-md" }, [
          h("h1", { key: "t1", className: "font-display text-2xl font-bold text-slate-900 dark:text-white" }, "Welcome back"),
          h("p", { key: "sub", className: "mt-1 text-sm text-slate-600 dark:text-slate-400" }, "Sign in to continue shopping."),
          h(
            "form",
            { key: "frm", className: "mt-6 space-y-4", onSubmit },
            [
              h(Field, { key: "f-email", label: "Email" }, h(TextInput, {
                type: "email",
                autoComplete: "email",
                value: email,
                onChange: (e) => setEmail(e.target.value),
                placeholder: "you@email.com",
                required: true
              })),
              h(Field, { key: "f-pass", label: "Password" }, h("div", { key: "pw-wrap", className: "relative" }, [
                h(TextInput, {
                  key: "pw",
                  type: show ? "text" : "password",
                  autoComplete: "current-password",
                  value: password,
                  onChange: (e) => setPassword(e.target.value),
                  placeholder: "••••••••",
                  className: "pr-12",
                  required: true
                }),
                h(
                  "button",
                  {
                    key: "eye",
                    type: "button",
                    className:
                      "tap-target absolute right-1 top-1/2 -translate-y-1/2 rounded-xl p-2 text-slate-500 hover:bg-white/40 dark:text-slate-400 dark:hover:bg-white/10",
                    onClick: () => setShow((s) => !s)
                  },
                  show ? h(EyeOff, { className: "h-5 w-5" }) : h(Eye, { className: "h-5 w-5" })
                )
              ])),
              err ? h("p", { key: "err", className: "text-sm text-rose-400" }, err) : null,
              h(Button, { key: "sub", type: "submit", className: "w-full", loading }, "Sign in"),
              h(
                "div",
                { key: "links", className: "flex flex-wrap justify-between gap-2 text-sm" },
                [
                  h(Link, { key: "fg", to: "/forgot-password", className: "text-sky-600 hover:underline dark:text-sky-300" }, "Forgot password?"),
                  h(Link, { key: "reg", to: "/register", className: "text-sky-600 hover:underline dark:text-sky-300" }, "Create account")
                ]
              )
            ]
          )
        ])
      ]
    )
  ]);
}

export function RegisterPage() {
  const nav = useNavigate();
  const { register } = useAuth();
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [password, setPassword] = useState("");
  const [show, setShow] = useState(false);
  const [role, setRole] = useState("buyer");
  const [verificationChannel, setVerificationChannel] = useState("email");
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);

  const onSubmit = async (e) => {
    e.preventDefault();
    setErr("");
    setLoading(true);
    try {
      if (verificationChannel === "sms" && !phone.trim()) {
        throw new Error("Phone is required for SMS verification");
      }
      await register({ email: email.trim(), phone: phone.trim(), password, role, verificationChannel });
      nav("/verify-email", { state: { email: email.trim(), phone: phone.trim(), name, channel: verificationChannel }, replace: true });
    } catch (ex) {
      setErr(ex.message || "Registration failed");
    } finally {
      setLoading(false);
    }
  };

  return h("div", { className: "relative min-h-screen overflow-hidden" }, [
    h(RefImage, {
      key: "bg",
      n: 18,
      alt: "",
      className: "pointer-events-none absolute inset-0 h-full w-full object-cover opacity-35 dark:opacity-20"
    }),
    h("div", {
      key: "overlay",
      className:
        "absolute inset-0 bg-gradient-to-b from-amber-50/90 via-slate-100/85 to-slate-200/90 dark:from-night-950/95 dark:via-night-950/90 dark:to-slate-950/95"
    }),
    h(
      "div",
      { key: "content", className: "relative z-10 mx-auto flex min-h-screen max-w-lg flex-col px-4 py-8 sm:px-6" },
      [
        h("div", { key: "topbar", className: "mb-6 flex items-center justify-between" }, [
          h(Link, { key: "home", to: "/shop", className: "flex items-center gap-2" }, [
            h(LogoMark, { key: "lm" }),
            h("span", { key: "nm", className: "font-display text-xl font-semibold text-slate-900 dark:text-white" }, "BrewMart")
          ]),
        ]),
        h(GlassPanel, { key: "panel", className: "mx-auto w-full max-w-md" }, [
          h("h1", { key: "t1", className: "font-display text-2xl font-bold text-slate-900 dark:text-white" }, "Join us"),
          h("p", { key: "sub", className: "mt-1 text-sm text-slate-600 dark:text-slate-400" }, "Create your account to get started."),
          h(
            "form",
            { key: "frm", className: "mt-6 space-y-4", onSubmit },
            [
              h(
                Field,
                {
                  key: "f-name",
                  label: h("span", { className: "inline-flex items-center gap-1" }, [
                    h(User, { key: "i", className: "h-3.5 w-3.5" }),
                    h("span", { key: "t" }, " Full name")
                  ])
                },
                h(TextInput, {
                  value: name,
                  onChange: (e) => setName(e.target.value),
                  placeholder: "John Doe",
                  autoComplete: "name"
                })
              ),
              h(
                Field,
                {
                  key: "f-email",
                  label: h("span", { className: "inline-flex items-center gap-1" }, [
                    h(Mail, { key: "i", className: "h-3.5 w-3.5" }),
                    h("span", { key: "t" }, " Email")
                  ])
                },
                h(TextInput, {
                  type: "email",
                  value: email,
                  onChange: (e) => setEmail(e.target.value),
                  placeholder: "your@email.com",
                  required: true,
                  autoComplete: "email"
                })
              ),
              h(
                Field,
                { key: "f-phone", label: "Phone (for SMS OTP, optional)" },
                h(TextInput, {
                  type: "tel",
                  value: phone,
                  onChange: (e) => setPhone(e.target.value),
                  placeholder: "+15551234567",
                  autoComplete: "tel"
                })
              ),
              h(Field, {
                key: "f-pass",
                label: h("span", { className: "inline-flex items-center gap-1" }, [
                  h(Lock, { key: "i", className: "h-3.5 w-3.5" }),
                  h("span", { key: "t" }, " Password")
                ])
              }, h("div", { key: "pw-stack", className: "space-y-1.5" }, [
                h("div", { key: "pw-row", className: "relative" }, [
                  h(TextInput, {
                    key: "pw",
                    type: show ? "text" : "password",
                    value: password,
                    onChange: (e) => setPassword(e.target.value),
                    placeholder: "••••••••",
                    className: "pr-12",
                    required: true,
                    autoComplete: "new-password",
                    minLength: 8
                  }),
                  h(
                    "button",
                    {
                      key: "eye",
                      type: "button",
                      className:
                        "tap-target absolute right-1 top-1/2 -translate-y-1/2 rounded-xl p-2 text-slate-500 hover:bg-white/40 dark:text-slate-400 dark:hover:bg-white/10",
                      onClick: () => setShow((s) => !s)
                    },
                    show ? h(EyeOff, { className: "h-5 w-5" }) : h(Eye, { className: "h-5 w-5" })
                  )
                ]),
                h(
                  "p",
                  { key: "hint", className: "text-xs text-slate-500 dark:text-slate-400" },
                  "8+ characters with upper, lower, number, and a symbol."
                )
              ])),
              h("div", { key: "role", className: "space-y-2" }, [
                h("p", { key: "rl", className: "text-xs font-semibold uppercase tracking-wide text-slate-500 dark:text-slate-400" }, "I am a…"),
                h("div", { key: "grid", className: "grid grid-cols-2 gap-2 sm:gap-3" }, [
                  h(
                    "button",
                    {
                      key: "buyer",
                      type: "button",
                      onClick: () => setRole("buyer"),
                      className: `tap-target rounded-2xl border px-3 py-3 text-sm font-medium transition sm:text-base ${
                        role === "buyer"
                          ? "border-sky-500/60 bg-sky-500/15 text-slate-900 dark:border-sky-400/50 dark:text-white"
                          : "border-slate-300/70 bg-white/30 text-slate-700 hover:bg-white/50 dark:border-white/10 dark:bg-white/5 dark:text-slate-200 dark:hover:bg-white/10"
                      }`
                    },
                    "Student (Buyer)"
                  ),
                  h(
                    "button",
                    {
                      key: "seller",
                      type: "button",
                      onClick: () => setRole("seller"),
                      className: `tap-target rounded-2xl border px-3 py-3 text-sm font-medium transition sm:text-base ${
                        role === "seller"
                          ? "border-sky-500/60 bg-sky-500/15 text-slate-900 dark:border-sky-400/50 dark:text-white"
                          : "border-slate-300/70 bg-white/30 text-slate-700 hover:bg-white/50 dark:border-white/10 dark:bg-white/5 dark:text-slate-200 dark:hover:bg-white/10"
                      }`
                    },
                    "Vendor (Seller)"
                  )
                ])
              ]),
              h("div", { key: "verify-channel", className: "space-y-2" }, [
                h("p", { key: "label", className: "text-xs font-semibold uppercase tracking-wide text-slate-500 dark:text-slate-400" }, "Verify via"),
                h("div", { key: "opts", className: "grid grid-cols-2 gap-2 sm:gap-3" }, [
                  h(
                    "button",
                    {
                      key: "by-email",
                      type: "button",
                      onClick: () => setVerificationChannel("email"),
                      className: `tap-target rounded-2xl border px-3 py-2 text-sm font-medium transition ${
                        verificationChannel === "email"
                          ? "border-sky-500/60 bg-sky-500/15 text-slate-900 dark:border-sky-400/50 dark:text-white"
                          : "border-slate-300/70 bg-white/30 text-slate-700 hover:bg-white/50 dark:border-white/10 dark:bg-white/5 dark:text-slate-200 dark:hover:bg-white/10"
                      }`
                    },
                    "Email OTP"
                  ),
                  h(
                    "button",
                    {
                      key: "by-sms",
                      type: "button",
                      onClick: () => setVerificationChannel("sms"),
                      className: `tap-target rounded-2xl border px-3 py-2 text-sm font-medium transition ${
                        verificationChannel === "sms"
                          ? "border-sky-500/60 bg-sky-500/15 text-slate-900 dark:border-sky-400/50 dark:text-white"
                          : "border-slate-300/70 bg-white/30 text-slate-700 hover:bg-white/50 dark:border-white/10 dark:bg-white/5 dark:text-slate-200 dark:hover:bg-white/10"
                      }`
                    },
                    "SMS OTP"
                  )
                ])
              ]),
              err ? h("p", { key: "err", className: "text-sm text-rose-400" }, err) : null,
              h(Button, { key: "sub", type: "submit", className: "w-full", loading }, "Create account"),
              h("p", { key: "foot", className: "text-center text-sm text-slate-600 dark:text-slate-400" }, [
                h("span", { key: "pre" }, "Already have an account? "),
                h(Link, { key: "ln", to: "/login", className: "font-semibold text-sky-600 hover:underline dark:text-sky-300" }, "Login")
              ])
            ].filter(Boolean)
          )
        ])
      ]
    )
  ]);
}

export function VerifyEmailPage() {
  const nav = useNavigate();
  const loc = useLocation();
  const email = loc.state?.email || "";
  const initialPhone = loc.state?.phone || "";
  const [channel, setChannel] = useState(loc.state?.channel === "sms" ? "sms" : "email");
  const [contact, setContact] = useState(loc.state?.channel === "sms" ? initialPhone : email);
  const [otp, setOtp] = useState("");
  const [msg, setMsg] = useState("");
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);

  const onSubmit = async (e) => {
    e.preventDefault();
    setErr("");
    setMsg("");
    setLoading(true);
    try {
      const payload = channel === "sms" ? { otp: otp.trim(), phone: contact.trim() } : { otp: otp.trim(), email: contact.trim() };
      await apiFetch("/api/auth/verify-email", { method: "POST", json: payload });
      nav("/login", { replace: true });
    } catch (ex) {
      setErr(ex.message || "Verification failed");
    } finally {
      setLoading(false);
    }
  };

  const resendOtp = async () => {
    setErr("");
    setMsg("");
    try {
      const payload = channel === "sms" ? { channel, phone: contact.trim() } : { channel, email: contact.trim() };
      const data = await apiFetch("/api/auth/send-otp", { method: "POST", json: payload });
      setMsg(data?.message || "OTP sent");
    } catch (ex) {
      setErr(ex.message || "Could not resend OTP");
    }
  };

  const { dark, toggle } = useTheme();
  return h("div", { className: "mx-auto max-w-md px-4 py-16" }, [
    h("div", { key: "top", className: "mb-4 flex justify-end" }, h(ThemeToggleButton, { dark, onToggle: toggle })),
    h(GlassPanel, { key: "panel" }, [
      h("h1", { key: "title", className: "font-display text-2xl font-bold text-slate-900 dark:text-white" }, "Verify email"),
      h("p", { key: "sub", className: "mt-2 text-sm text-slate-600 dark:text-slate-400" }, "Enter the OTP we sent to your chosen contact."),
      h(
        "form",
        { key: "form", className: "mt-6 space-y-4", onSubmit },
        [
          h("div", { key: "channel", className: "grid grid-cols-2 gap-2" }, [
            h(
              "button",
              {
                key: "email",
                type: "button",
                className: `tap-target rounded-2xl border px-3 py-2 text-sm font-medium ${channel === "email" ? "border-sky-500/60 bg-sky-500/15" : "border-slate-300/70 bg-white/30 dark:border-white/10 dark:bg-white/5"}`,
                onClick: () => {
                  setChannel("email");
                  setContact(email);
                }
              },
              "Email"
            ),
            h(
              "button",
              {
                key: "sms",
                type: "button",
                className: `tap-target rounded-2xl border px-3 py-2 text-sm font-medium ${channel === "sms" ? "border-sky-500/60 bg-sky-500/15" : "border-slate-300/70 bg-white/30 dark:border-white/10 dark:bg-white/5"}`,
                onClick: () => {
                  setChannel("sms");
                  setContact(initialPhone);
                }
              },
              "SMS"
            )
          ]),
          h(Field, { key: "contact", label: channel === "sms" ? "Phone number" : "Email" }, h(TextInput, {
            type: channel === "sms" ? "tel" : "email",
            value: contact,
            onChange: (e) => setContact(e.target.value),
            required: true
          })),
          h(Field, { key: "otp", label: "One-time password (OTP)" }, h(TextInput, { value: otp, onChange: (e) => setOtp(e.target.value), required: true })),
          msg && h("p", { key: "msg", className: "text-sm text-emerald-400" }, msg),
          err && h("p", { key: "err", className: "text-sm text-rose-400" }, err),
          h(Button, { key: "submit", type: "submit", className: "w-full", loading }, "Verify"),
          h(Button, { key: "resend", variant: "ghost", type: "button", className: "w-full", onClick: resendOtp }, "Resend OTP"),
          h(Link, { key: "back", to: "/login", className: "block text-center text-sm text-sky-600 hover:underline dark:text-sky-300" }, "Back to login")
        ].filter(Boolean)
      )
    ])
  ]);
}

export function ForgotPasswordPage() {
  const { dark, toggle } = useTheme();
  const [email, setEmail] = useState("");
  const [msg, setMsg] = useState("");
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);

  const onSubmit = async (e) => {
    e.preventDefault();
    setErr("");
    setMsg("");
    setLoading(true);
    try {
      await apiFetch("/api/auth/forgot-password", { method: "POST", json: { email: email.trim() } });
      setMsg("If that email exists, a reset token was sent.");
    } catch (ex) {
      setErr(ex.message || "Request failed");
    } finally {
      setLoading(false);
    }
  };

  return h("div", { className: "mx-auto max-w-md px-4 py-16" }, [
    h("div", { key: "top", className: "mb-4 flex justify-end" }, h(ThemeToggleButton, { dark, onToggle: toggle })),
    h(GlassPanel, { key: "panel" }, [
      h("h1", { key: "title", className: "font-display text-2xl font-bold text-slate-900 dark:text-white" }, "Reset password"),
      h("form", { key: "form", className: "mt-6 space-y-4", onSubmit }, [
        h(Field, { key: "email", label: "Email" }, h(TextInput, { type: "email", value: email, onChange: (e) => setEmail(e.target.value), required: true })),
        msg && h("p", { key: "msg", className: "text-sm text-emerald-400" }, msg),
        err && h("p", { key: "err", className: "text-sm text-rose-400" }, err),
        h(Button, { key: "submit", type: "submit", className: "w-full", loading }, "Send token"),
        h(Link, { key: "back", to: "/login", className: "block text-center text-sm text-sky-600 hover:underline dark:text-sky-300" }, "Back to login")
      ].filter(Boolean))
    ])
  ]);
}

export function ResetPasswordPage() {
  const { dark, toggle } = useTheme();
  const [token, setToken] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);
  const nav = useNavigate();

  const onSubmit = async (e) => {
    e.preventDefault();
    setErr("");
    setLoading(true);
    try {
      await apiFetch("/api/auth/reset-password", {
        method: "POST",
        json: { token: token.trim(), newPassword }
      });
      nav("/login", { replace: true });
    } catch (ex) {
      setErr(ex.message || "Reset failed");
    } finally {
      setLoading(false);
    }
  };

  return h("div", { className: "mx-auto max-w-md px-4 py-16" }, [
    h("div", { key: "top", className: "mb-4 flex justify-end" }, h(ThemeToggleButton, { dark, onToggle: toggle })),
    h(GlassPanel, { key: "panel" }, [
      h("h1", { key: "title", className: "font-display text-2xl font-bold text-slate-900 dark:text-white" }, "New password"),
      h("form", { key: "form", className: "mt-6 space-y-4", onSubmit }, [
        h(Field, { key: "token", label: "Reset token" }, h(TextInput, { value: token, onChange: (e) => setToken(e.target.value), required: true })),
        h(Field, { key: "newpw", label: "New password" }, h(TextInput, { type: "password", value: newPassword, onChange: (e) => setNewPassword(e.target.value), required: true, minLength: 8 })),
        err && h("p", { key: "err", className: "text-sm text-rose-400" }, err),
        h(Button, { key: "submit", type: "submit", className: "w-full", loading }, "Update password")
      ].filter(Boolean))
    ])
  ]);
}
